// src/contexto/AuthContext.jsx
import React, { createContext, useContext, useEffect, useState } from "react";
import { login as apiLogin, getMe as apiGetMe, logout as apiLogout } from "../services/auth.service";

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const isAuthenticated = !!user;

  // Al montar, intenta recuperar sesión (por cookie si el back ya está listo, o mock si USE_MOCK)
  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const { user: me } = await apiGetMe();
        if (mounted) setUser(me);
      } catch {
        if (mounted) setUser(null);
      }
    })();
    return () => { mounted = false; };
  }, []);

  const login = async ({ identifier, password }) => {
    try {
      const { user: logged } = await apiLogin({ identifier, password });
      setUser(logged);
      return logged;
    } catch (e) {
      setUser(null);
      throw e; // para que tu Login.jsx muestre el mensaje
    }
  };

  const logout = async () => {
    try {
      await apiLogout();
    } finally {
      setUser(null);
    }
  };

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
